/**
 * 统一智能体平台内置轻量级高性能 Markdown 渲染引擎
 * 支持：标题、粗体/斜体、代码块（含语言高亮头部与一键复制）、行内代码、引用、列表、表格、水平线、链接与段落。
 */
(function (global) {
  function escapeHtml(str) {
    if (!str) return "";
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function renderMarkdown(md) {
    if (!md) return "";
    let text = md.replace(/\r\n/g, "\n").replace(/\r/g, "\n");

    // 1. 提取并替换代码块 ```lang\ncode\n```
    const codeBlocks = [];
    text = text.replace(/```([a-zA-Z0-9_-]*)\n([\s\S]*?)```/g, function (_, lang, code) {
      const id = "CODE_BLOCK_" + codeBlocks.length;
      lang = lang.trim() || "text";
      const cleanCode = code.replace(/\n$/, "");
      const blockHtml = `
        <div class="code-block-wrapper">
          <div class="code-header">
            <span class="code-lang">${escapeHtml(lang)}</span>
            <button class="copy-code-btn" onclick="copyCodeText(this)">📋 复制</button>
          </div>
          <pre class="code-content"><code class="language-${escapeHtml(lang)}">${escapeHtml(cleanCode)}</code></pre>
        </div>
      `;
      codeBlocks.push({ id, html: blockHtml });
      return id;
    });

    // 2. 表格解析 | Header | Header |\n| --- | --- |\n| Cell | Cell |
    text = text.replace(/((?:^|\n)\|[^\n]+\|\n\|(?:\s*[-:]+[-|\s:]*)\|\n(?:\|[^\n]+\|\n?)+)/g, function (match) {
      const lines = match.trim().split("\n");
      if (lines.length < 3) return match;
      const headers = lines[0].split("|").slice(1, -1).map(c => c.trim());
      const rows = lines.slice(2).map(line => line.split("|").slice(1, -1).map(c => c.trim()));

      let tableHtml = '<div class="table-responsive"><table class="md-table"><thead><tr>';
      headers.forEach(h => {
        tableHtml += `<th>${inlineFormat(h)}</th>`;
      });
      tableHtml += "</tr></thead><tbody>";
      rows.forEach(r => {
        tableHtml += "<tr>";
        r.forEach(c => {
          tableHtml += `<td>${inlineFormat(c)}</td>`;
        });
        tableHtml += "</tr>";
      });
      tableHtml += "</tbody></table></div>";
      return "\n" + tableHtml + "\n";
    });

    // 3. 标题解析 (# H1 ~ #### H4)
    text = text.replace(/^#### (.*?)$/gm, "<h4>$1</h4>");
    text = text.replace(/^### (.*?)$/gm, "<h3>$1</h3>");
    text = text.replace(/^## (.*?)$/gm, "<h2>$1</h2>");
    text = text.replace(/^# (.*?)$/gm, "<h1>$1</h1>");

    // 4. 水平线 (--- / ***)
    text = text.replace(/^(?:---|___|\*\*\*)$/gm, '<hr class="md-divider" />');

    // 5. 引用块 (> Quote)
    text = text.replace(/^(?:> (.*?)(?:\n|$))+/gm, function (match) {
      const content = match.split("\n").map(l => l.replace(/^> ?/, "")).join("<br/>");
      return `<blockquote class="md-blockquote">${inlineFormat(content)}</blockquote>`;
    });

    // 6. 无序列表 (- / * / +)
    text = text.replace(/^[\*\-\+] (.*?)$/gm, '<li class="md-li-bullet">$1</li>');
    // 有序列表 (1. 2. 3.)
    text = text.replace(/^\d+\. (.*?)$/gm, '<li class="md-li-number">$1</li>');

    // 包装 <li> 进 <ul> / <ol>
    text = text.replace(/(<li class="md-li-bullet">.*?<\/li>(\n?))+/gs, function (m) {
      return `<ul class="md-ul">${m}</ul>`;
    });
    text = text.replace(/(<li class="md-li-number">.*?<\/li>(\n?))+/gs, function (m) {
      return `<ol class="md-ol">${m}</ol>`;
    });

    // 7. 行内格式化
    text = inlineFormat(text);

    // 8. 段落解析 (按双换行切分)
    const paragraphs = text.split(/\n{2,}/);
    text = paragraphs
      .map(p => {
        p = p.trim();
        if (!p) return "";
        if (/^<(h[1-6]|div|table|blockquote|ul|ol|hr|pre)/.test(p)) {
          return p;
        }
        return `<p class="md-p">${p.replace(/\n/g, "<br/>")}</p>`;
      })
      .filter(Boolean)
      .join("\n");

    // 9. 还原代码块
    codeBlocks.forEach(cb => {
      text = text.replace(new RegExp("<p class=\"md-p\">" + cb.id + "</p>|" + cb.id, "g"), cb.html);
    });

    return text;
  }

  function inlineFormat(str) {
    if (!str) return "";
    return str
      // 行内代码 `code`
      .replace(/`([^`]+)`/g, '<code class="inline-code">$1</code>')
      // 粗体 **bold**
      .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
      // 斜体 *italic*
      .replace(/\*([^*]+)\*/g, "<em>$1</em>")
      // 删除线 ~~deleted~~
      .replace(/~~([^~]+)~~/g, "<del>$1</del>")
      // 链接 [text](url)
      .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener" class="md-link">$1</a>');
  }

  // 复制代码函数
  global.copyCodeText = function (btn) {
    const wrapper = btn.closest(".code-block-wrapper");
    if (!wrapper) return;
    const codeEl = wrapper.querySelector("code");
    if (!codeEl) return;
    const text = codeEl.innerText || codeEl.textContent;
    navigator.clipboard.writeText(text).then(() => {
      const orig = btn.innerHTML;
      btn.innerHTML = "✅ 已复制";
      btn.classList.add("copied");
      setTimeout(() => {
        btn.innerHTML = orig;
        btn.classList.remove("copied");
      }, 2000);
    }).catch(err => {
      console.error("复制失败:", err);
    });
  };

  global.marked = { parse: renderMarkdown };
})(window);